<?php
declare(strict_types=1);
final class AutonomyBudgetRepository implements AutonomyBudgetStoreInterface{
 private const MAP=['decisions'=>'decisions_consumed','tasks'=>'tasks_consumed','replans'=>'replans_consumed','input_tokens'=>'input_tokens_consumed','output_tokens'=>'output_tokens_consumed','tool_calls'=>'tool_calls_consumed','write_tool_calls'=>'write_tool_calls_consumed','runtime_seconds'=>'runtime_seconds_consumed'];
 private const REASONS=['tasks'=>'task_limit_reached','decisions'=>'decision_limit_reached','replans'=>'replan_limit_reached','input_tokens'=>'input_token_limit_reached','output_tokens'=>'output_token_limit_reached','tool_calls'=>'tool_limit_reached','write_tool_calls'=>'write_limit_reached','runtime_seconds'=>'runtime_limit_reached'];
 public function __construct(private mysqli$db){}
 public function startCycle(int$u,int$p,string$public):array{$this->db->begin_transaction();try{$policy=$this->policy($u,$p,true);if(!$policy)throw new TaskNotFoundException('autonomy_policy_not_found');$existing=$this->active($u,$p,true);if($existing){$this->db->commit();return$existing;}$s=$this->p("INSERT INTO ProjectAutonomyCycles(public_id,policy_id_,user_id_,project_id_,status) VALUES(?,?,?,?,'active')");$policyId=(int)$policy['id_'];$s->bind_param('siii',$public,$policyId,$u,$p);$this->x($s);$s->close();$row=$this->active($u,$p,true)??throw new RuntimeException('autonomy_cycle_create_failed');$this->db->commit();return$row;}catch(Throwable$e){$this->db->rollback();throw$e;}}
 public function findActiveCycle(int$u,int$p):?array{return$this->active($u,$p,false);}
 public function reserve(int$u,int$p,string$cyclePublic,string$key,AutonomyBudgetRequest$r,AutonomyPolicy$policy):AutonomyBudgetReservation{$this->key($key);$this->db->begin_transaction();try{$lockedPolicy=$this->policy($u,$p,true);if(!$lockedPolicy){$this->db->rollback();return new AutonomyBudgetReservation(false,'invalid_scope',null,false,[],[]);}$effective=AutonomyPolicy::fromRow($lockedPolicy);if($effective->mode==='disabled'){$this->db->rollback();return new AutonomyBudgetReservation(false,'autonomy_disabled',null,false,[],[]);}if($effective->status!=='active'){$this->db->rollback();return new AutonomyBudgetReservation(false,'autonomy_'.$effective->status,null,false,[],[]);}$policy=$effective;$cycle=$this->cycle($u,$p,$cyclePublic,true);if(!$cycle||(int)$cycle['policy_id_']!==(int)$lockedPolicy['id_']||$cycle['status']!=='active'){$this->db->rollback();return new AutonomyBudgetReservation(false,'budget_unavailable',null,false,[],[]);}$existing=$this->reservation((int)$cycle['id_'],$key,true);if($existing){if(!$this->same($existing,$r))throw new TaskConcurrencyException('autonomy_idempotency_conflict');if($existing['status']==='released'){$this->db->commit();return new AutonomyBudgetReservation(false,'reservation_released',(string)$existing['public_id'],true,$this->usage($cycle),$this->remaining($cycle,$policy));}$result=$this->result($cycle,$policy,(string)$existing['public_id'],true);$this->db->commit();return$result;}$values=$r->values();if($r->descendantDepth>$policy->limits['max_descendant_depth']){$this->db->rollback();return new AutonomyBudgetReservation(false,'depth_limit_reached',null,false,$this->usage($cycle),$this->remaining($cycle,$policy));}$limits=['decisions'=>'max_decisions_per_cycle','tasks'=>'max_tasks_per_cycle','replans'=>'max_replans_per_cycle','input_tokens'=>'max_input_tokens','output_tokens'=>'max_output_tokens','tool_calls'=>'max_tool_calls','write_tool_calls'=>'max_write_tool_calls','runtime_seconds'=>'max_runtime_seconds'];foreach(self::MAP as$input=>$column){if((int)$cycle[$column]+$values[$input]>$policy->limits[$limits[$input]]){$this->db->rollback();return new AutonomyBudgetReservation(false,self::REASONS[$input],null,false,$this->usage($cycle),$this->remaining($cycle,$policy));}}$reservationPublic=TaskPublicId::generate();$s=$this->p("INSERT INTO ProjectAutonomyReservations(public_id,cycle_id_,user_id_,project_id_,idempotency_key,status,decisions,tasks,replans,input_tokens,output_tokens,tool_calls,write_tool_calls,runtime_seconds,descendant_depth) VALUES(?,?,?,?,?,'reserved',?,?,?,?,?,?,?,?,?)");$cycleId=(int)$cycle['id_'];$s->bind_param('siiisiiiiiiiii',$reservationPublic,$cycleId,$u,$p,$key,$values['decisions'],$values['tasks'],$values['replans'],$values['input_tokens'],$values['output_tokens'],$values['tool_calls'],$values['write_tool_calls'],$values['runtime_seconds'],$values['descendant_depth']);$this->x($s);$s->close();$s=$this->p('UPDATE ProjectAutonomyCycles SET decisions_consumed=decisions_consumed+?,tasks_consumed=tasks_consumed+?,replans_consumed=replans_consumed+?,input_tokens_consumed=input_tokens_consumed+?,output_tokens_consumed=output_tokens_consumed+?,tool_calls_consumed=tool_calls_consumed+?,write_tool_calls_consumed=write_tool_calls_consumed+?,runtime_seconds_consumed=runtime_seconds_consumed+?,lock_version=lock_version+1 WHERE id_=? AND status=\'active\'');$s->bind_param('iiiiiiiii',$values['decisions'],$values['tasks'],$values['replans'],$values['input_tokens'],$values['output_tokens'],$values['tool_calls'],$values['write_tool_calls'],$values['runtime_seconds'],$cycleId);$this->x($s);if($s->affected_rows!==1)throw new TaskConcurrencyException('autonomy_budget_conflict');$s->close();$cycle=$this->cycle($u,$p,$cyclePublic,true)??throw new RuntimeException('autonomy_cycle_missing');$result=$this->result($cycle,$policy,$reservationPublic,false);$this->db->commit();return$result;}catch(Throwable$e){$this->db->rollback();throw$e;}}
 public function consume(int$u,int$p,string$public):array{return$this->transition($u,$p,$public,'reserved','consumed',false);}
 public function release(int$u,int$p,string$public):array{return$this->transition($u,$p,$public,'reserved','released',true);}
 private function transition(int$u,int$p,string$public,string$from,string$to,bool$refund):array{$this->db->begin_transaction();try{$s=$this->p('SELECT r.*,c.status cycle_status FROM ProjectAutonomyReservations r JOIN ProjectAutonomyCycles c ON c.id_=r.cycle_id_ WHERE r.public_id=? AND r.user_id_=? AND r.project_id_=? FOR UPDATE');$s->bind_param('sii',$public,$u,$p);$this->x($s);$row=$s->get_result()->fetch_assoc();$s->close();if(!$row)throw new TaskNotFoundException('reservation_not_found');if($row['status']===$to){$this->db->commit();return$row;}if($row['status']!==$from)throw new TaskTransitionException('reservation_not_transitionable');$s=$this->p("UPDATE ProjectAutonomyReservations SET status=?,consumed_at=IF(?='consumed',UTC_TIMESTAMP(6),consumed_at),released_at=IF(?='released',UTC_TIMESTAMP(6),released_at) WHERE id_=? AND status='reserved'");$id=(int)$row['id_'];$s->bind_param('sssi',$to,$to,$to,$id);$this->x($s);if($s->affected_rows!==1)throw new TaskConcurrencyException('autonomy_reservation_conflict');$s->close();if($refund){$s=$this->p('UPDATE ProjectAutonomyCycles SET decisions_consumed=decisions_consumed-?,tasks_consumed=tasks_consumed-?,replans_consumed=replans_consumed-?,input_tokens_consumed=input_tokens_consumed-?,output_tokens_consumed=output_tokens_consumed-?,tool_calls_consumed=tool_calls_consumed-?,write_tool_calls_consumed=write_tool_calls_consumed-?,runtime_seconds_consumed=runtime_seconds_consumed-?,lock_version=lock_version+1 WHERE id_=?');$cycle=(int)$row['cycle_id_'];$s->bind_param('iiiiiiiii',$row['decisions'],$row['tasks'],$row['replans'],$row['input_tokens'],$row['output_tokens'],$row['tool_calls'],$row['write_tool_calls'],$row['runtime_seconds'],$cycle);$this->x($s);$s->close();}$row['status']=$to;$this->db->commit();return$row;}catch(Throwable$e){$this->db->rollback();throw$e;}}
 private function result(array$c,AutonomyPolicy$p,string$public,bool$idempotent):AutonomyBudgetReservation{return new AutonomyBudgetReservation(true,'reserved',$public,$idempotent,$this->usage($c),$this->remaining($c,$p));}
 private function usage(array$c):array{$out=[];foreach(self::MAP as$key=>$column)$out[$key]=(int)$c[$column];return$out;}
 private function remaining(array$c,AutonomyPolicy$p):array{$limits=['decisions'=>'max_decisions_per_cycle','tasks'=>'max_tasks_per_cycle','replans'=>'max_replans_per_cycle','input_tokens'=>'max_input_tokens','output_tokens'=>'max_output_tokens','tool_calls'=>'max_tool_calls','write_tool_calls'=>'max_write_tool_calls','runtime_seconds'=>'max_runtime_seconds'];$out=[];foreach(self::MAP as$key=>$column)$out[$key]=max(0,$p->limits[$limits[$key]]-(int)$c[$column]);return$out;}
 private function policy(int$u,int$p,bool$lock):?array{$sql='SELECT a.* FROM ProjectAutonomyPolicies a JOIN Projects x ON x.id_=a.project_id_ AND x.user_id_=a.user_id_ WHERE a.user_id_=? AND a.project_id_=?'.($lock?' FOR UPDATE':'');$s=$this->p($sql);$s->bind_param('ii',$u,$p);$this->x($s);$r=$s->get_result()->fetch_assoc();$s->close();return$r?:null;}
 private function active(int$u,int$p,bool$lock):?array{$sql="SELECT * FROM ProjectAutonomyCycles WHERE user_id_=? AND project_id_=? AND status='active'".($lock?' FOR UPDATE':'').' LIMIT 1';$s=$this->p($sql);$s->bind_param('ii',$u,$p);$this->x($s);$r=$s->get_result()->fetch_assoc();$s->close();return$r?:null;}
 private function cycle(int$u,int$p,string$public,bool$lock):?array{$sql='SELECT * FROM ProjectAutonomyCycles WHERE public_id=? AND user_id_=? AND project_id_=?'.($lock?' FOR UPDATE':'').' LIMIT 1';$s=$this->p($sql);$s->bind_param('sii',$public,$u,$p);$this->x($s);$r=$s->get_result()->fetch_assoc();$s->close();return$r?:null;}
 private function reservation(int$cycle,string$key,bool$lock):?array{$sql='SELECT * FROM ProjectAutonomyReservations WHERE cycle_id_=? AND idempotency_key=?'.($lock?' FOR UPDATE':'').' LIMIT 1';$s=$this->p($sql);$s->bind_param('is',$cycle,$key);$this->x($s);$r=$s->get_result()->fetch_assoc();$s->close();return$r?:null;}
 private function same(array$row,AutonomyBudgetRequest$r):bool{foreach($r->values()as$key=>$value)if((int)$row[$key]!==$value)return false;return true;}
 private function key(string$key):void{if($key===''||strlen($key)>128||!preg_match('/^[A-Za-z0-9][A-Za-z0-9_.:-]{0,127}$/D',$key))throw new TaskValidationException('autonomy_idempotency_key_invalid');}
 private function p(string$q):mysqli_stmt{$s=$this->db->prepare($q);if(!$s)throw new RuntimeException('database_error');return$s;}private function x(mysqli_stmt$s):void{if(!$s->execute())throw new RuntimeException('database_error');}
}
